import{_ as e}from"./chunks/theme-light.BboWfE89.js";import{_ as o,o as d,c as a,a3 as r}from"./chunks/framework.B3OtXxrP.js";const b=JSON.parse('{"title":"Writing in Blank","description":"","frontmatter":{},"headers":[],"relativePath":"guide/writing.md","filePath":"guide/writing.md"}'),n={name:"guide/writing.md"};function c(i,t,s,h,l,u){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="writing-in-blank" tabindex="-1">Writing in Blank <a class="header-anchor" href="#writing-in-blank" aria-label="Permalink to &quot;Writing in Blank&quot;">​</a></h1><p>Blank shows your text as it will look, not as markdown syntax. There are no toolbars: you format with <a href="./shortcuts">keyboard shortcuts</a> or by typing markdown, which Blank turns into formatting as you go.</p><img class="shot" src="'+e+'" alt="A document in Blank&#39;s light theme"><h2 id="format-as-you-type" tabindex="-1">Format as you type <a class="header-anchor" href="#format-as-you-type" aria-label="Permalink to &quot;Format as you type&quot;">​</a></h2><p>At the start of an empty line, type one of these to turn the line into a block:</p><table tabindex="0"><thead><tr><th>Type at the start of a line</th><th>Then</th><th>You get</th></tr></thead><tbody><tr><td><code>#</code> … <code>######</code></td><td>Space</td><td>Heading 1–6</td></tr><tr><td><code>-</code> <code>*</code> <code>+</code></td><td>Space</td><td>Bullet list</td></tr><tr><td><code>1.</code> (any number)</td><td>Space</td><td>Numbered list</td></tr><tr><td><code>&gt;</code></td><td>Space</td><td>Blockquote</td></tr><tr><td><code>---</code> <code>***</code> <code>___</code></td><td>Enter</td><td>Horizontal line</td></tr><tr><td><code>```</code> or <code>```lang</code></td><td>Enter</td><td>Code block</td></tr></tbody></table><p>Inline markdown works too: <code>**bold**</code>, <code>*italic*</code>, <code>`code`</code>, <code>[title](url)</code> and plain URLs become formatting once you finish the word. See <a href="./autocorrect">Autocorrect</a> for everything Blank corrects.</p><h2 id="blank-remembers-your-document" tabindex="-1">Blank remembers your document <a class="header-anchor" href="#blank-remembers-your-document" aria-label="Permalink to &quot;Blank remembers your document&quot;">​</a></h2><p>Blank keeps what you write as you go, a moment after you stop typing, and restores it on the next start, together with the open file, the theme and the language. So you can close the window mid-thought without saving.</p><h2 id="save-open-and-export" tabindex="-1">Save, open and export <a class="header-anchor" href="#save-open-and-export" aria-label="Permalink to &quot;Save, open and export&quot;">​</a></h2><p>Documents are plain markdown files, so any other editor can open them.</p><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>New file</td><td><code>Mod</code> <code>N</code></td></tr><tr><td>Open file</td><td><code>Mod</code> <code>O</code></td></tr><tr><td>Save</td><td><code>Mod</code> <code>S</code></td></tr><tr><td>Save as</td><td><code>Mod</code> <code>Shift</code> <code>S</code></td></tr><tr><td>Export as PDF</td><td><code>Mod</code> <code>Alt</code> <code>P</code></td></tr></tbody></table><p><code>Mod</code> is <code>Cmd</code> on macOS and <code>Ctrl</code> on Windows and Linux.</p><h2 id="the-status-bar" tabindex="-1">The status bar <a class="header-anchor" href="#the-status-bar" aria-label="Permalink to &quot;The status bar&quot;">​</a></h2><p>The top of the window shows the open file, or <em>Untitled</em>. The bottom shows the word and character count and the <a href="./autocorrect#language">autocorrect language</a>.</p>',15)])])}const f=o(n,[["render",c]]);export{b as __pageData,f as default};
